const final=["qualify_grid.py","fault_cases.py","caller.py","CONTRACT.md","COVERAGE.md","DEPENDENCY_NOTES.md","SOURCE_DEPENDENCIES.json","SOURCE_IDENTITIES.json","AUTHOR_CHECKS.json","HANDOFF.md","HANDOFF.json"].sort();
need(eq(Object.keys(S.actual_input_roles_qp04_only).sort(),["certificate","original_source","original_manuscript","assignment","accepted_predecessor","accepted_manual_review"].sort()),"runtime role set");Object.values(S.actual_input_roles_qp04_only).forEach(pin);
